import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Anti-XSS filter - does NOT protect against SQL injection
    private String sanitizeOutput(String input) {
        if (input == null) return null;
        return input.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
    }

    // Validates report type against allowed enum
    private boolean isValidReportType(String type) {
        return Pattern.matches("^(sales|inventory|audit|payroll)$", type);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String department = req.getParameter("dept");

        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation - format check only
        if (startDate != null && !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date format");
            return;
        }
        if (endDate != null && !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date format");
            return;
        }

        // Sort column - whitelist check
        if (sortCol != null && !sortCol.matches("^(date|amount|name|id)$")) {
            sortCol = "date";
        }

        // Department parameter - used in query construction
        // Developer note: dept comes from internal dropdown, should be safe
        String query = "SELECT r.id, r.created_at, r.amount, r.description, d.name " +
                      "FROM reports r JOIN departments d ON r.dept_id = d.id " +
                      "WHERE r.report_type = ? " +
                      "AND r.created_at >= ? AND r.created_at <= ? ";

        if (department != null && !department.isEmpty()) {
            // Vulnerable: string concatenation with user input
            query += "AND d.name = '" + department + "' ";
        }

        query += "ORDER BY r." + sortCol;

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, reportType);
            stmt.setString(2, startDate);
            stmt.setString(3, endDate);

            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("{\"id\":%d,\"date\":\"%s\",\"amount\":%.2f,\"desc\":\"%s\",\"dept\":\"%s\"}",
                    rs.getInt(1),
                    sanitizeOutput(rs.getString(2)),
                    rs.getDouble(3),
                    sanitizeOutput(rs.getString(4)),
                    sanitizeOutput(rs.getString(5)));
            }
            out.print("\n]");

        } catch (SQLException e) {
            // Log full error for debugging
            getServletContext().log("Query failed: " + query, e);
            resp.sendError(500, "Report generation failed");
        }
    }
}
